#!/usr/bin/env bash
# honesty-guard — тест має падати, коли код зламаний.
#
# Це не стильова перевірка. Зелений набір, який видає ту саму відповідь на
# справній і на зламаній системі, гірший за відсутній: він займає місце
# перевірки, яку через нього ніхто не напише. Цей сторож ловить найдешевші
# способи отримати зелений колір, не отримавши доказу.
#
# Дивиться ТІЛЬКИ на ДОДАНІ рядки. Наявний код не чіпає — інакше кожен PR
# відповідав би за все, що колись написали до нього, і сторож вимкнули б.
#
# Свідомо НЕ ловить: асерт, підігнаний під фактичний результат. Машині це
# невидиме — тому воно лишається предметом рев'ю керуючого вузла.

set -uo pipefail

DIFF="$(git diff --unified=0 "${BASE_SHA}...${HEAD_SHA}" -- '*.cs' 2>/dev/null || true)"

if [ -z "$DIFF" ]; then
  printf '\033[32m✓ honesty-guard: змін у .cs немає\033[0m\n'
  exit 0
fi

REPORT="$(printf '%s\n' "$DIFF" | awk '
  # Поточний файл і номер рядка в новій версії.
  /^\+\+\+ b\// { file = substr($0, 7); next }
  /^@@/ {
    # @@ -a,b +c,d @@
    match($0, /\+[0-9]+/)
    line = substr($0, RSTART + 1, RLENGTH - 1) + 0
    next
  }
  /^\+/ && !/^\+\+\+/ {
    text = substr($0, 2)

    # ── 1. Тавтологічний асерт ────────────────────────────────────────────
    if (text ~ /Assert\.True[[:space:]]*\([[:space:]]*true[[:space:]]*\)/ ||
        text ~ /Assert\.False[[:space:]]*\([[:space:]]*false[[:space:]]*\)/) {
      emit(file, line, "тавтологічний асерт — нічого не перевіряє", text)
    }

    # ── 2. Вимкнений тест ─────────────────────────────────────────────────
    if (text ~ /Skip[[:space:]]*=/ || text ~ /\[Ignore/) {
      emit(file, line, "тест вимкнено (Skip/Ignore)", text)
    }

    # ── 3. Закоментований атрибут тесту ───────────────────────────────────
    if (text ~ /^[[:space:]]*\/\/[[:space:]]*\[(Fact|Theory)/) {
      emit(file, line, "атрибут тесту закоментовано", text)
    }

    # ── 4. Порожній catch ─────────────────────────────────────────────────
    # Однорядковий: catch { } / catch (Exception) { }
    if (text ~ /catch[[:space:]]*(\([^)]*\))?[[:space:]]*\{[[:space:]]*\}/) {
      emit(file, line, "порожній catch — помилку проковтнуто", text)
    }

    # ── 5. Заглушка в бойовому коді ───────────────────────────────────────
    # Лише src/: у tools/ є відомі одноразові утиліти-заглушки.
    if (file ~ /^src\// && text ~ /NotImplementedException/) {
      emit(file, line, "NotImplementedException у бойовому коді", text)
    }
    if (text ~ /Assert\.Fail[[:space:]]*\([[:space:]]*"not implemented"/) {
      emit(file, line, "залишок заглушки етапу 0", text)
    }

    # ── Облік для евристики 6 ─────────────────────────────────────────────
    if (file ~ /^tests\//) {
      if (text ~ /\[(Fact|Theory)([[:space:]]*\(|\])/) tests[file]++
      if (text ~ /Assert\./ || text ~ /\.Received[[:space:]]*\(/ ||
          text ~ /Assert$/) asserts[file]++
    }

    line++
    next
  }
  { next }

  function emit(f, l, why, src) {
    gsub(/^[[:space:]]+/, "", src)
    printf "%s:%s\n    %s\n    > %s\n\n", f, l, why, src
    bad = 1
  }

  END {
    # ── 6. Доданий тест без жодного асерту у файлі ───────────────────────
    for (f in tests) {
      if (!(f in asserts)) {
        printf "%s\n    додано %d тест(и) і НІ ОДНОГО асерту в цьому файлі\n    > перевірка, яка нічого не стверджує, гірша за відсутню\n\n", f, tests[f]
        bad = 1
      }
    }
    exit 0
  }
')"

if [ -n "$REPORT" ]; then
  printf '\n\033[31m✗ honesty-guard: знайдено нечесні перевірки\033[0m\n\n'
  # ⚠ `printf '%s\n\n'`, не `'%s'`: підстановка $(...) зрізає кінцеві переводи
  # рядків, і остання знахідка злипалася з текстом правила нижче.
  printf '%s\n\n' "$REPORT" | sed 's/^/  /'
  cat <<'MSG'
  Правило: тест, що не падає на зламаному коді, доказом не є.
  Червоний CI із чесною причиною коштує один цикл; зелений із підробленим
  асертом коштує тижні, бо помилку знайдуть у продакшні.

  Що робити: переписати перевірку так, щоб вона падала на невиправленому
  коді. Довести це можна відкатом: зламай рядок, який тест стереже, — тест
  мусить впасти.

  Якщо якийсь із випадків вище — виправданий (наприклад, catch навмисно
  порожній і причина названа в коментарі), це рішення керуючого вузла:
  коментар в issue з обґрунтуванням і мітка `needs:pk1`.
MSG
  exit 1
fi

printf '\033[32m✓ honesty-guard: нечесних перевірок не знайдено\033[0m\n'
